    lbl('CLASSICAL · martingale FCLT (Whitt) · Doob transform (Champagnat–Villemonais) · recurrence criterion (Fukushima–Oshima–Takeda 1.6.3) · van Trees (Gill–Levit)', W / 2, 470, '#8fbcff', Q(S, 1, 'are classical inputs') * fade, 14);
    lbl('VOLUME · tensor and point limit · survival laws · path limits · ranks · Green laws · hidden circle · covers · memory · quartic · observation · n^(−1/2) · calibration', W / 2, 515, C.orange, Q(S, 1, 'the rest is argued in the theory volume') * fade, 14);
    lbl('RECOMPUTED · M₀ and band Hessian · survival series · Q paths · Yukawa integrals · image sums · tails · memory equation · quartic value · residues · risk slope', W / 2, 560, C.white, Q(S, 1, 'the finite computations were redone') * fade, 14);
    lbl('NO LEAN-FROZEN DECLARATION IS USED IN THIS FILM', W / 2, 650, C.gold, Q(S, 1, 'the finite computations were redone', 0.6, 1.2) * fade, 22);
